 <body>
 <div class="shell"><header class="topbar"><div class="brand">✦ 잿빛 항로 <span>방랑자의 기록</span></div><div class="top-actions"><button class="quiet" id="saveBtn">기록 저장</button><button class="quiet" id="resetBtn">새 여정</button></div></header>
 <section id="creator"></section><main id="game" class="hidden"></main></div><div id="modalRoot"></div><div id="toastRoot"></div>
 <script>
+const RACES=[{id:'human',name:'인간',desc:'어디에나 적응하는 여행자',bonus:'모든 능력치 +1'}, {id:'elf',name:'엘프',desc:'숲과 마력의 오래된 수호자',bonus:'민첩 +2 · 지혜 +1'}, {id:'dwarf',name:'드워프',desc:'산맥에서 단련된 장인',bonus:'체력 +2 · 힘 +1'}, {id:'beastkin',name:'수인',desc:'예민한 감각과 야성의 피',bonus:'민첩 +2 · 감각 +1'}, {id:'sylvan',name:'실바',desc:'자연의 숨결을 읽는 종족',bonus:'지혜 +2 · 감각 +1'}, {id:'ashen',name:'잿빛 혈족',desc:'오래전 마법의 재에서 태어난 자',bonus:'지혜 +2 · 체력 +1'}];
+const MASTERY=[{id:'blade',name:'검술',icon:'⚔',desc:'검을 휘둘러 전장을 지배한다',skill:'연속 베기'}, {id:'bow',name:'궁술',icon:'➶',desc:'멀리서 약점을 꿰뚫는다',skill:'관통 사격'}, {id:'arcane',name:'비전 마법',icon:'✧',desc:'마나를 다뤄 불꽃과 보호막을 부른다',skill:'화염구'}, {id:'herbal',name:'약초 채집',icon:'❀',desc:'풀잎의 효능과 숨은 군락을 찾는다',skill:'정밀 채집'}, {id:'mining',name:'광맥 탐사',icon:'⛏',desc:'암맥을 읽어 귀한 광물을 캐낸다',skill:'맥 짚기'}, {id:'tracking',name:'추적과 사냥',icon:'♧',desc:'흔적을 좇아 먹잇감을 찾아낸다',skill:'기습 사냥'}];
+const STAT_NAMES={str:'힘',dex:'민첩',vit:'체력',wis:'지혜'};const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
+let create={name:'',gender:'여성',race:'human',stats:{str:2,dex:2,vit:2,wis:2},mastery:'blade'};
+function renderCreator(){const race=RACES.find(x=>x.id===create.race);$('#creator').innerHTML=`<div class="panel"><div class="hero"><div class="eyebrow">A text adventure · 01 / 06</div><h1 class="title">잿빛 너머, 새로운 길</h1><p class="subtitle">지도 끝의 미지로 떠나는 당신만의 판타지 여정.</p></div><div class="creator-body"><div class="form-grid"><div class="field"><label>방랑자의 이름</label><input id="charName" maxlength="16" placeholder="이름을 적어주세요" value="${esc(create.name)}"></div><div class="field"><label>성별</label><div class="choice-row">${['여성','남성','논바이너리'].map(g=>`<button class="choice ${create.gender===g?'active':''}" data-gender="${g}">${g}</button>`).join('')}</div></div><div class="field" style="grid-column:1/-1"><label>종족 · ${race.bonus}</label><div class="race-grid">${RACES.map(r=>`<button class="pick-card ${create.race===r.id?'active':''}" data-race="${r.id}"><strong>${r.name}</strong><small>${r.desc}</small><em>${r.bonus}</em></button>`).join('')}</div></div><div class="field" style="grid-column:1/-1"><label>초기 능력치 <span style="color:var(--muted)">— 분배할 점수 <b id="pointsLeft">2</b></span></label><div class="stats-editor">${Object.entries(create.stats).map(([k,v])=>`<div class="stat-control"><span>${STAT_NAMES[k]}</span><button data-stat="${k}" data-delta="-1">−</button><b>${v}</b><button data-stat="${k}" data-delta="1">+</button></div>`).join('')}</div></div><div class="field" style="grid-column:1/-1"><label>첫 마스터리 · 시작 기술이 해금됩니다</label><div class="mastery-grid">${MASTERY.map(m=>`<button class="pick-card ${create.mastery===m.id?'active':''}" data-mastery="${m.id}"><strong>${m.icon} ${m.name}</strong><small>${m.desc}</small><em>시작 기술: ${m.skill}</em></button>`).join('')}</div></div></div><div class="form-footer"><span class="footnote">모든 선택은 여정 중 성장의 방향을 바꿉니다.</span><button class="btn" id="beginBtn">여정 시작하기　→</button></div></div></div>`;
+$('#charName').addEventListener('input',e=>create.name=e.target.value);document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>{create.gender=b.dataset.gender;renderCreator()});document.querySelectorAll('[data-race]').forEach(b=>b.onclick=()=>{create.race=b.dataset.race;renderCreator()});document.querySelectorAll('[data-mastery]').forEach(b=>b.onclick=()=>{create.mastery=b.dataset.mastery;renderCreator()});document.querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>{let sum=Object.values(create.stats).reduce((a,b)=>a+b,0),k=b.dataset.stat,d=+b.dataset.delta;if(d<0&&create.stats[k]>1)create.stats[k]--;if(d>0&&sum<10)create.stats[k]++;renderCreator()});$('#beginBtn').onclick=startGame;$('#pointsLeft').textContent=10-Object.values(create.stats).reduce((a,b)=>a+b,0)}

