const REGIONS=[{id:'moss',name:'이끼 낀 변경숲',icon:'🌲',desc:'낮은 안개와 오래된 발자국',danger:1,story:'나무들이 바람에 몸을 기울인다. 축축한 흙 아래 오래된 길의 흔적이 이어진다.'},{id:'ridge',name:'바람깎인 능선',icon:'⛰️',desc:'광맥과 매서운 바람',danger:2,story:'돌바람이 뺨을 스친다. 바위틈마다 푸른 광맥이 희미하게 반짝인다.'},{id:'marsh',name:'달빛 늪지',icon:'🌙',desc:'희귀한 약초와 낯선 울음',danger:2,story:'물안개 사이로 푸른 꽃이 빛난다. 수면 아래 무언가가 당신의 발걸음을 좇는다.'}];
let game=null;function freshGame(){let race=RACES.find(r=>r.id===create.race),stats={...create.stats};if(create.race==='human')Object.keys(stats).forEach(k=>stats[k]++);if(create.race==='elf'){stats.dex+=2;stats.wis++}if(create.race==='dwarf'){stats.vit+=2;stats.str++}if(create.race==='beastkin'){stats.dex+=2;stats.wis++}if(create.race==='sylvan'){stats.wis+=2;stats.dex++}if(create.race==='ashen'){stats.wis+=2;stats.vit++}return{name:create.name.trim()||'이름 없는 방랑자',gender:create.gender,race,stats,mastery:{blade:0,bow:0,arcane:0,herbal:0,mining:0,tracking:0},unlocked:[],startMastery:create.mastery,hp:30+stats.vit*3,maxHp:30+stats.vit*3,mana:12+stats.wis*2,maxMana:12+stats.wis*2,level:1,xp:0,day:1,region:'moss',inventory:{'말린 식량':3,'약초':1},gold:8,log:[],visited:['moss'],combat:null,turn:0}}function startGame(){game=freshGame();game.mastery[create.mastery]=2;game.unlocked.push(MASTERY.find(m=>m.id===create.mastery).skill);game.log.push({type:'system',text:`${game.name}은(는) 낡은 나침반 하나를 쥐고 변경숲의 길에 들어섰다. 모든 여정은 작은 흔적에서 시작된다.`});$('#creator').classList.add('hidden');$('#game').classList.remove('hidden');renderGame();saveGame(false)}
function log(text,type=''){game.log.push({text,type});if(game.log.length>35)game.log.shift()}function currentRegion(){return REGIONS.find(r=>r.id===game.region)}function addItem(n,q=1){game.inventory[n]=(game.inventory[n]||0)+q}function takeItem(n,q=1){if((game.inventory[n]||0)<q)return false;game.inventory[n]-=q;if(!game.inventory[n])delete game.inventory[n];return true}function gainMastery(id,amount=1){let m=MASTERY.find(x=>x.id===id);if(!m)return;let before=game.mastery[id];game.mastery[id]+=amount;let now=game.mastery[id];let unlocks=({blade:[3,'회전 베기',6,'방패 가르기'],bow:[3,'정밀 조준',6,'연발 사격'],arcane:[3,'서리 창',6,'비전 방벽'],herbal:[3,'약초 감별',6,'풍요의 손길'],mining:[3,'광맥 감지',6,'정교한 채굴'],tracking:[3,'덫 설치',6,'치명적 급습']})[id];for(let i=0;i<unlocks.length;i+=2){if(before<unlocks[i]&&now>=unlocks[i]){game.unlocked.push(unlocks[i+1]);log(`마스터리 성장! ${m.name} ${now}단계 — 「${unlocks[i+1]}」 기술을 익혔다.`, 'system');toast(`기술 해금: ${unlocks[i+1]}`)}}}
function gainXp(n){game.xp+=n;while(game.xp>=game.level*30){game.xp-=game.level*30;game.level++;game.maxHp+=5;game.maxMana+=2;game.hp=game.maxHp;game.mana=game.maxMana;log(`경험을 쌓아 레벨 ${game.level}이 되었다. 체력과 마력이 회복된다.`,'system');toast(`레벨 ${game.level} 달성!`)}}
function tick(){game.turn++;if(game.turn%5===0){game.day++;if(!takeItem('말린 식량')){game.hp=Math.max(1,game.hp-3);log('식량이 떨어져 허기가 진다. 체력 3을 잃었다.','system')}else log('야영지에서 식량 한 끼를 먹었다.')} }
function toast(msg){let root=$('#toastRoot');root.innerHTML=`<div class="toast">${esc(msg)}</div>`;setTimeout(()=>root.innerHTML='',1900)}

