 function gainXp(n){game.xp+=n;while(game.xp>=game.level*30){game.xp-=game.level*30;game.level++;game.maxHp+=5;game.maxMana+=2;game.hp=game.maxHp;game.mana=game.maxMana;log(`경험을 쌓아 레벨 ${game.level}이 되었다. 체력과 마력이 회복된다.`,'system');toast(`레벨 ${game.level} 달성!`)}}
 function tick(){game.turn++;if(game.turn%5===0){game.day++;if(!takeItem('말린 식량')){game.hp=Math.max(1,game.hp-3);log('식량이 떨어져 허기가 진다. 체력 3을 잃었다.','system')}else log('야영지에서 식량 한 끼를 먹었다.')} }
 function toast(msg){let root=$('#toastRoot');root.innerHTML=`<div class="toast">${esc(msg)}</div>`;setTimeout(()=>root.innerHTML='',1900)}
