,q])=>`<div class="resource"><span>${n}</span><b>×${q}</b></div>`).join('')}</div>`:'<div class="empty-note">가방이 비어 있습니다.</div>'}<div class="footnote">짐은 길 위에서 얻고, 야영 때 식량을 소모합니다.</div></section></aside><section class="middle"><div class="region-head"><div class="eyebrow">제 ${game.day}일째 · 탐험 중</div><h1 class="title">${r.icon} ${r.name}</h1><p class="subtitle">${r.desc}</p><div class="region-meta"><span class="chip">위험도 ${'◆'.repeat(r.danger)}${'◇'.repeat(3-r.danger)}</span><span class="chip">${game.region==='moss'?'숲길':game.region==='ridge'?'고산 지대':'늪지'}</span><span class="chip">오전 ${8+(game.turn%12)}시</span></div></div><div class="panel region-view"><div class="story" id="story">${game.log.map(l=>`<div class="time">${l.type==='system'?'✦ 여정의 기록':'— 주변의 흔적'}</div><p class="${l.type==='system'?'system':''}">${esc(l.text)}</p>`).join('')}</div><div class="actions-title"><h3 style="font:17px var(--serif);margin:0">무엇을 할까?</h3><span class="tiny">행동은 시간과 숙련을 쌓습니다</span></div><div class="actions-grid"><button class="action" data-action="explore"><span class="icon">🧭</span><strong>주변 탐색</strong><small>흔적과 사건을 발견한다</small></button><button class="action" data-action="hunt"><span class="icon">🏹</span><strong>사냥하기</strong><small>먹잇감을 추적하고 전투한다</small></button><button class="action" data-action="herbal"><span class="icon">🌿</span><strong>약초 채집</strong><small>풀과 버섯을 채집한다</small></button><button class="action" data-action="mine"><span class="icon">⛏️</span><strong>광물 채굴</strong><small>광석과 돌을 캐낸다</small></button><button class="action" data-action="craft"><span class="icon">⚒️</span><strong>제작과 조리</strong><small>재료를 도구와 물자로 바꾼다</small></button><button class="action" data-action="rest"><span class="icon">🔥</span><strong>야영과 휴식</strong><small>체력과 마나를 회복한다</small></button></div></div></section><aside class="rightbar"><section class="panel card"><div class="section-head"><h3>여행 지도</h3><span class="tiny">장소 ${game.visited.length}/3</span></div><div class="location-list">${REGIONS.map(loc=>`<div class="location ${loc.id===game.region?'active':''}" data-travel="${loc.id}"><span class="locicon">${loc.icon}</span><div><strong>${loc.name}</strong><small>${game.visited.includes(loc.id)?'방문함':'미답 지역'} · 위험 ${loc.danger}/3</small></div><span class="arr">${loc.id===game.region?'●':'›'}</span></div>`).join('')}</div><div class="footnote">새 장소로 이동하면 탐험 기회가 열립니다.</div></section><section class="panel card"><div class="section-head"><h3>마스터리</h3><span class="tiny">활동으로 성장</span></div>${mastery}</section></aside></div>`;
