function action(kind){if(game.combat){toast('전투 중에는 다른 행동을 할 수 없습니다.');return}if(kind==='craft'){openCraft();return}if(kind==='rest'){rest();return}tick();if(kind==='explore')explore();if(kind==='hunt')hunt();if(kind==='herbal')gather('herbal');if(kind==='mine')gather('mining');renderGame();saveGame(false)}
function gather(type){let reg=game.region,herb=type==='herbal',options=herb?(reg==='marsh'?['달빛 이끼','약초','약초']:['약초','약초','쓴풀']):(reg==='ridge'?['철광석','철광석','수정']:['돌 조각','철광석']);let item=options[Math.floor(Math.random()*options.length)],qty=Math.random()<.25?2:1;addItem(item,qty);gainMastery(type);log(`${herb?'풀잎 사이에서':'바위 틈에서'} ${item} ${qty}개를 얻었다.${game.mastery[type]>=3&&game.mastery[type]-(qty===2?0:1)>=2?' 숙련된 손길로 채집이 한결 수월해졌다.':''}`);if(Math.random()<.16&&reg!=='moss'){log('덤불에서 작은 생물이 튀어나왔다!');beginCombat('늪지 들개',12+game.level*2,4,3)}}
function hunt(){gainMastery('tracking');let difficulty=currentRegion().danger;let names=game.region==='marsh'?['늪지 들개','독침 멧돼지','안개 도마뱀']:game.region==='ridge'?['산양','바위늑대','절벽 독수리']:['숲토끼','뿔사슴','숲늑대'];let name=names[Math.floor(Math.random()*names.length)];if(Math.random()<.18&&difficulty===1){addItem('말린 식량',1);gainXp(4);log(`발자국을 따라가 작은 사냥감의 흔적을 찾았다. 말린 식량 1개를 챙겼다.`);return}let hp=10+game.level*3+difficulty*5;log(`흙에 선명한 발자국이 찍혀 있다. ${name}이(가) 모습을 드러냈다!`);beginCombat(name,hp,4+difficulty*2,3+difficulty)}
function explore(){let roll=Math.random();if(roll<.23){let found=game.region==='ridge'?'은화':game.region==='marsh'?'달빛 이끼':'말린 식량';let q=found==='은화'?4+Math.floor(Math.random()*6):1; if(found==='은화')game.gold+=q;else addItem(found,q);log(`낡은 흔적을 살피다 ${found} ${q>1?q+'개':''}을 발견했다.`);gainXp(5)}else if(roll<.52){log(currentRegion().story);gainMastery('tracking');gainXp(3)}else if(roll<.8){let name=game.region==='marsh'?'안개 사냥꾼':game.region==='ridge'?'바위늑대':'숲늑대';log(`길가에서 위협적인 기척이 다가온다. ${name}과(와) 마주쳤다!`);beginCombat(name,12+game.level*3,5+currentRegion().danger,4)}else{let q=1+Math.floor(Math.random()*2);addItem('약초',q);log(`바람에 실린 향을 따라가 약초 ${q}개를 찾았다.`);gainMastery('herbal');gainXp(4)}}
function travel(id){if(id===game.region)return;if(game.combat){toast('전투가 끝난 뒤 이동할 수 있습니다.');return}tick();let first=!game.visited.includes(id);game.region=id;if(first){game.visited.push(id);log(`${currentRegion().name}에 도착했다. 낯선 풍경이 눈앞에 펼쳐지고, 지도의 가장자리가 넓어졌다.`,'system');gainXp(8)}else log(`${currentRegion().name}(으)로 되돌아왔다.`);renderGame();saveGame(false)}
function rest(){tick();if(game.hp<game.maxHp||game.mana<game.maxMana){game.hp=Math.min(game.maxHp,game.hp+Math.ceil(game.maxHp*.42));game.mana=Math.min(game.maxMana,game.mana+Math.ceil(game.maxMana*.55));log('작은 불가에 몸을 녹이며 숨을 골랐다. 체력과 마나가 회복되었다.','system')}else{log('하늘 아래 잠시 쉬며 다음 길을 가늠했다.');}if(!takeItem('말린 식량')){game.hp=Math.max(1,game.hp-4);log('식량 없이 야영했다. 허기로 체력 4를 잃었다.')}renderGame();saveGame(false)}
const RECIPES=[{name:'약초 연고',desc:'체력 12 회복',in:{'약초':2},out:'약초 연고',qty:1},{name:'말린 식량',desc:'여행 식량 2인분',in:{'쓴풀':1},out:'말린 식량',qty:2},{name:'철제 화살촉',desc:'은화 5개',in:{'철광석':2},out:'은화',qty:5},{name:'수정 부적',desc:'마나 10 회복',in:{'수정':1,'달빛 이끼':1},out:'수정 부적',qty:1},{name:'야영용 도구',desc:'다음 휴식 체력 회복 +',in:{'철광석':1,'돌 조각':2},out:'야영용 도구',qty:1}];
function openCraft(){let root=$('#modalRoot');root.innerHTML=`<div class="modal-back" id="craftBack"><div class="modal"><div class="modal-head"><div><div class="eyebrow">작업대 · 보유 재료로 제작</div><h2>제작과 조리</h2></div><button class="close" data-close>×</button></div><div class="recipe-list">${RECIPES.map((r,i)=>{let ok=Object.entries(r.in).every(([n,q])=>(game.inventory[n]||0)>=q);return `<button class="recipe" data-recipe="${i}" ${ok?'':'disabled'}><span><strong>${r.name}</strong><small>${Object.entries(r.in).map(([n,q])=>`${n} ×${q}`).join(' · ')}</small></span><span class="tiny">${r.desc}</span></button>`}).join('')}</div><p class="footnote">제작 숙련은 해당 마스터리 활동으로 오릅니다.</p></div></div>`;root.querySelector('[data-close]').onclick=()=>root.innerHTML='';root.querySelector('#craftBack').onclick=e=>{if(e.target.id==='craftBack')root.innerHTML=''};root.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>craft(+b.dataset.recipe))}
function craft(i){let rec=RECIPES[i];if(!Object.entries(rec.in).every(([n,q])=>(game.inventory[n]||0)>=q)){toast('재료가 부족합니다.');return}Object.entries(rec.in).forEach(([n,q])=>takeItem(n,q));if(rec.out==='은화')game.gold+=rec.qty;else addItem(rec.out,rec.qty);if(rec.out==='약초 연고')log('약초를 빻아 상처에 바를 연고를 만들었다.');else log(`${rec.name}을(를) 완성했다.`);gainMastery('herbal');tick();$('#modalRoot').innerHTML='';renderGame();saveGame(false)}

