 function toast(msg){let root=$('#toastRoot');root.innerHTML=`<div class="toast">${esc(msg)}</div>`;setTimeout(()=>root.innerHTML='',1900)}
 function renderGame(){if(!game)return;let r=currentRegion(),mastery=MASTERY.map(m=>{let v=game.mastery[m.id],unlocks=({blade:[3,'회전 베기',6,'방패 가르기'],bow:[3,'정밀 조준',6,'연발 사격'],arcane:[3,'서리 창',6,'비전 방벽'],herbal:[3,'약초 감별',6,'풍요의 손길'],mining:[3,'광맥 감지',6,'정교한 채굴'],tracking:[3,'덫 설치',6,'치명적 급습']})[m.id];return `<div class="skill-row ${v===0?'locked':''}"><span class="dot"></span><span class="skill-name">${m.icon} ${m.name}</span><b>${v}</b></div>${unlocks.map((x,i)=>i%2===0?`<div class="skill-row ${v>=x?'':'locked'}"><span class="dot"></span><span class="skill-name">${unlocks[i+1]} <small>(숙련 ${x})</small></span>${v>=x?'<b>해금</b>':''}</div>`:'').join('')}`}).join('');let inv=Object.entries(game.inventory).filter(x=>x[1]>0);$('#game').innerHTML=`<div class="game-layout"><aside class="sidebar"><section class="panel char-card"><div class="avatar">${game.race.id==='elf'?'🧝':game.race.id==='dwarf'?'🧔':game.race.id==='beastkin'?'🐺':game.race.id==='sylvan'?'🧚':game.race.id==='ashen'?'🧙':'🧭'}</div><div><h2 class="char-name">${esc(game.name)}</h2><div class="race-line">${game.gender} ${game.race.name} · 레벨 ${game.level}</div><div class="statline">${Object.entries(game.stats).map(([k,v])=>`<span class="chip">${STAT_NAMES[k]} ${v}</span>`).join('')}</div></div><div class="stat-bars"><div><div class="bar-head"><span>체력</span><span>${game.hp} / ${game.maxHp}</span></div><div class="bar"><i style="width:${game.hp/game.maxHp*100}%"></i></div></div><div><div class="bar-head"><span>마나</span><span>${game.mana} / ${game.maxMana}</span></div><div class="bar mana"><i style="width:${game.mana/game.maxMana*100}%"></i></div></div><div><div class="bar-head"><span>경험치 · 다음 레벨</span><span>${game.xp} / ${game.level*30}</span></div><div class="bar xp"><i style="width:${game.xp/(game.level*30)*100}%"></i></div></div></div></section><section class="panel card"><div class="section-head"><h3>소지품</h3><span class="tiny">◈ ${game.gold} 은화</span></div>${inv.length?`<div class="resource-list">${inv.map(([n,q])=>`<div class="resource"><span>${n}</span><b>×${q}</b></div>`).join('')}</div>`:'<div class="empty-note">가방이 비어 있습니다.</div>'}<div class="footnote">짐은 길 위에서 얻고, 야영 때 식량을 소모합니다.</div></section></aside><section class="middle"><div class="region-head"><div class="eyebrow">제 ${game.day}일째 · 탐험 중</div><h1 class="title">${r.icon} ${r.name}</h1><p class="subtitle">${r.desc}</p><div class="region-meta"><span class="chip">위험도 ${'◆'.repeat(r.danger)}${'◇'.repeat(3-r.danger)}</span><span class="chip">${game.region==='moss'?'숲길':game.region==='ridge'?'고산 지대':'늪지'}</span><span class="chip">오전 ${8+(game.turn%12)}시</span></div></div><div class="panel region-view"><div class="story" id="story">${game.log.map(l=>`<div class="time">${l.type==='system'?'✦ 여정의 기록':'— 주변의 흔적'}</div><p class="${l.type==='system'?'system':''}">${esc(l.text)}</p>`).join('')}</div><div class="actions-title"><h3 style="font:17px var(--serif);margin:0">무엇을 할까?</h3><span class="tiny">행동은 시간과 숙련을 쌓습니다</span></div><div class="actions-grid"><button class="action" data-action="explore"><span class="icon">🧭</span><strong>주변 탐색</strong><small>흔적과 사건을 발견한다</small></button><button class="action" data-action="hunt"><span class="icon">🏹</span><strong>사냥하기</strong><small>먹잇감을 추적하고 전투한다</small></button><button class="action" data-action="herbal"><span class="icon">🌿</span><strong>약초 채집</strong><small>풀과 버섯을 채집한다</small></button><button class="action" data-action="mine"><span class="icon">⛏️</span><strong>광물 채굴</strong><small>광석과 돌을 캐낸다</small></button><button class="action" data-action="craft"><span class="icon">⚒️</span><strong>제작과 조리</strong><small>재료를 도구와 물자로 바꾼다</small></button><button class="action" data-action="rest"><span class="icon">🔥</span><strong>야영과 휴식</strong><small>체력과 마나를 회복한다</small></button></div></div></section><aside class="rightbar"><section class="panel card"><div class="section-head"><h3>여행 지도</h3><span class="tiny">장소 ${game.visited.length}/3</span></div><div class="location-list">${REGIONS.map(loc=>`<div class="location ${loc.id===game.region?'active':''}" data-travel="${loc.id}"><span class="locicon">${loc.icon}</span><div><strong>${loc.name}</strong><small>${game.visited.includes(loc.id)?'방문함':'미답 지역'} · 위험 ${loc.danger}/3</small></div><span class="arr">${loc.id===game.region?'●':'›'}</span></div>`).join('')}</div><div class="footnote">새 장소로 이동하면 탐험 기회가 열립니다.</div></section><section class="panel card"><div class="section-head"><h3>마스터리</h3><span class="tiny">활동으로 성장</span></div>${mastery}</section></aside></div>`;
 $('#story').scrollTop=$('#story').scrollHeight;document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>travel(b.dataset.travel));}
 function action(kind){if(game.combat){toast('전투 중에는 다른 행동을 할 수 없습니다.');return}if(kind==='craft'){openCraft();return}if(kind==='rest'){rest();return}tick();if(kind==='explore')explore();if(kind==='hunt')hunt();if(kind==='herbal')gather('herbal');if(kind==='mine')gather('mining');renderGame();saveGame(false)}
+function gather(type){let reg=game.region,herb=type==='herbal',options=herb?(reg==='marsh'?['달빛 이끼','약초','약초']:['약초','약초','쓴풀']):(reg==='ridge'?['철광석','철광석','수정']:['돌 조각','철광석']);let item=options[Math.floor(Math.random()*options.length)],qty=Math.random()<.25?2:1;addItem(item,qty);gainMastery(type);log(`${herb?'풀잎 사이에서':'바위 틈에서'} ${item} ${qty}개를 얻었다.${game.mastery[type]>=3&&game.mastery[type]-(qty===2?0:1)>=2?' 숙련된 손길로 채집이 한결 수월해졌다.':''}`);if(Math.random()<.16&&reg!=='moss'){log('덤불에서 작은 생물이 튀어나왔다!');beginCombat('늪지 들개',12+game.level*2,4,3)}}
+function hunt(){gainMastery('tracking');let difficulty=currentRegion().danger;let names=game.region==='marsh'?['늪지 들개','독침 멧돼지','안개 도마뱀']:game.region==='ridge'?['산양','바위늑대','절벽 독수리']:['숲토끼','뿔사슴','숲늑대'];let name=names[Math.floor(Math.random()*names.length)];if(Math.random()<.18&&difficulty===1){addItem('말린 식량',1);gainXp(4);log(`발자국을 따라가 작은 사냥감의 흔적을 찾았다. 말린 식량 1개를 챙겼다.`);return}let hp=10+game.level*3+difficulty*5;log(`흙에 선명한 발자국이 찍혀 있다. ${name}이(가) 모습을 드러냈다!`);beginCombat(name,hp,4+difficulty*2,3+difficulty)}
+function explore(){let roll=Math.random();if(roll<.23){let found=game.region==='ridge'?'은화':game.region==='marsh'?'달빛 이끼':'말린 식량';let q=found==='은화'?4+Math.floor(Math.random()*6):1; if(found==='은화')game.gold+=q;else addItem(found,q);log(`낡은 흔적을 살피다 ${found} ${q>1?q+'개':''}을 발견했다.`);gainXp(5)}else if(roll<.52){log(currentRegion().story);gainMastery('tracking');gainXp(3)}else if(roll<.8){let name=game.region==='marsh'?'안개 사냥꾼':game.region==='ridge'?'바위늑대':'숲늑대';log(`길가에서 위협적인 기척이 다가온다. ${name}과(와) 마주쳤다!`);beginCombat(name,12+game.level*3,5+currentRegion().danger,4)}else{let q=1+Math.floor(Math.random()*2);addItem('약초',q);log(`바람에 실린 향을 따라가 약초 ${q}개를 찾았다.`);gainMastery('herbal');gainXp(4)}}
+function travel(id){if(id===game.region)return;if(game.combat){toast('전투가 끝난 뒤 이동할 수 있습니다.');return}tick();let first=!game.visited.includes(id);game.region=id;if(first){game.visited.push(id);log(`${currentRegion().name}에 도착했다. 낯선 풍경이 눈앞에 펼쳐지고, 지도의 가장자리가 넓어졌다.`,'system');gainXp(8)}else log(`${currentRegion().name}(으)로 되돌아왔다.`);renderGame();saveGame(false)}
+function rest(){tick();if(game.hp<game.maxHp||game.mana<game.maxMana){game.hp=Math.min(game.maxHp,game.hp+Math.ceil(game.maxHp*.42));game.mana=Math.min(game.maxMana,game.mana+Math.ceil(game.maxMana*.55));log('작은 불가에 몸을 녹이며 숨을 골랐다. 체력과 마나가 회복되었다.','system')}else{log('하늘 아래 잠시 쉬며 다음 길을 가늠했다.');}if(!takeItem('말린 식량')){game.hp=Math.max(1,game.hp-4);log('식량 없이 야영했다. 허기로 체력 4를 잃었다.')}renderGame();saveGame(false)}
+const RECIPES=[{name:'약초 연고',desc:'체력 12 회복',in:{'약초':2},out:'약초 연고',qty:1},{name:'말린 식량',desc:'여행 식량 2인분',in:{'쓴풀':1},out:'말린 식량',qty:2},{name:'철제 화살촉',desc:'은화 5개',in:{'철광석':2},out:'은화',qty:5},{name:'수정 부적',desc:'마나 10 회복',in:{'수정':1,'달빛 이끼':1},out:'수정 부적',qty:1},{name:'야영용 도구',desc:'다음 휴식 체력 회복 +',in:{'철광석':1,'돌 조각':2},out:'야영용 도구',qty:1}];
+function openCraft(){let root=$('#modalRoot');root.innerHTML=`<div class="modal-back" id="craftBack"><div class="modal"><div class="modal-head"><div><div class="eyebrow">작업대 · 보유 재료로 제작</div><h2>제작과 조리</h2></div><button class="close" data-close>×</button></div><div class="recipe-list">${RECIPES.map((r,i)=>{let ok=Object.entries(r.in).every(([n,q])=>(game.inventory[n]||0)>=q);return `<button class="recipe" data-recipe="${i}" ${ok?'':'disabled'}><span><strong>${r.name}</strong><small>${Object.entries(r.in).map(([n,q])=>`${n} ×${q}`).join(' · ')}</small></span><span class="tiny">${r.desc}</span></button>`}).join('')}</div><p class="footnote">제작 숙련은 해당 마스터리 활동으로 오릅니다.</p></div></div>`;root.querySelector('[data-close]').onclick=()=>root.innerHTML='';root.querySelector('#craftBack').onclick=e=>{if(e.target.id==='craftBack')root.innerHTML=''};root.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>craft(+b.dataset.recipe))}
+function craft(i){let rec=RECIPES[i];if(!Object.entries(rec.in).every(([n,q])=>(game.inventory[n]||0)>=q)){toast('재료가 부족합니다.');return}Object.entries(rec.in).forEach(([n,q])=>takeItem(n,q));if(rec.out==='은화')game.gold+=rec.qty;else addItem(rec.out,rec.qty);if(rec.out==='약초 연고')log('약초를 빻아 상처에 바를 연고를 만들었다.');else log(`${rec.name}을(를) 완성했다.`);gainMastery('herbal');tick();$('#modalRoot').innerHTML='';renderGame();saveGame(false)}

