function renderCombat(message=''){if(!game.combat)return;let c=game.combat,abilities=game.unlocked.filter(x=>['연속 베기','회전 베기','방패 가르기','관통 사격','정밀 조준','연발 사격','화염구','서리 창','비전 방벽','치명적 급습'].includes(x));let skillButtons=abilities.map(x=>`<button data-fight="skill:${x}">✦ ${x}${['화염구','서리 창','비전 방벽'].includes(x)?' · 마나 4':''}</button>`).join('');$('#modalRoot').innerHTML=`<div class="modal-back"><div class="modal"><div class="modal-head"><div><div class="eyebrow">조우 · 턴제 전투</div><h2>⚔ ${esc(c.name)}</h2></div><span class="chip">적 체력 ${c.hp} / ${c.maxHp}</span></div><div class="encounter"><div class="enemy-top"><strong>${esc(c.name)}</strong><span>위협도 ${'◆'.repeat(Math.min(3,Math.ceil(c.damage/3)))}</span></div><div class="bar" style="margin-top:9px"><i style="width:${c.hp/c.maxHp*100}%;background:var(--red)"></i></div></div><div class="combat-log">${esc(message||'상대가 빈틈을 노린다.')}</div><div class="combat-actions"><button data-fight="attack">⚔ 기본 공격</button>${skillButtons}<button data-fight="potion">✚ 약초 연고 사용 (${game.inventory['약초 연고']||0})</button><button data-fight="flee">↗ 도주 시도</button></div><p class="footnote">체력 ${game.hp}/${game.maxHp} · 마나 ${game.mana}/${game.maxMana} · 행동마다 상대가 반격합니다.</p></div></div>`;document.querySelectorAll('[data-fight]').forEach(b=>b.onclick=()=>fight(b.dataset.fight))}
function fight(move){let c=game.combat;if(!c)return;let msg='',damage=0;if(move==='flee'){if(Math.random()<.58){log(`${c.name}에게서 무사히 벗어났다.`);game.combat=null;$('#modalRoot').innerHTML='';renderGame();saveGame(false);return}else msg='도주로가 막혔다!'}else if(move==='potion'){if(takeItem('약초 연고')){game.hp=Math.min(game.maxHp,game.hp+12);msg='약초 연고를 발랐다. 체력 12 회복.'}else msg='사용할 약초 연고가 없다.'}else if(move.startsWith('skill:')){let sk=move.slice(6);if(['화염구','서리 창','비전 방벽'].includes(sk)){if(game.mana<4){msg='마나가 부족하다!';damage=0}else{game.mana-=4;damage=8+game.stats.wis*2+Math.floor(game.mastery.arcane/2);if(sk==='비전 방벽'){game.hp=Math.min(game.maxHp,game.hp+5);damage=Math.floor(damage*.65)}gainMastery('arcane');msg=`${sk} 발동! 마법의 힘으로 ${damage} 피해를 주었다.`}}else if(['관통 사격','정밀 조준','연발 사격'].includes(sk)){damage=6+game.stats.dex*2+Math.floor(game.mastery.bow/2);gainMastery('bow');msg=`${sk}! 정확한 사격으로 ${damage} 피해.`}else if(['치명적 급습'].includes(sk)){damage=7+game.stats.dex*2+game.mastery.tracking;gainMastery('tracking');msg=`기습으로 급소를 노려 ${damage} 피해.`}else{damage=7+game.stats.str*2+game.mastery.blade;gainMastery('blade');msg=`${sk}! 검을 휘둘러 ${damage} 피해.`}}else{damage=4+game.stats.str+game.stats.dex+Math.floor(Math.random()*4);gainMastery(game.startMastery==='bow'?'bow':'blade');msg=`무기를 휘둘러 ${damage} 피해를 주었다.`}c.hp=Math.max(0,c.hp-damage);if(c.hp<=0){let loot=c.name.includes('사슴')||c.name.includes('토끼')||c.name.includes('산양')?'말린 식량':'가죽';addItem(loot,1);if(Math.random()<.45)addItem('말린 식량',1);game.gold+=2+Math.floor(Math.random()*4);gainXp(c.xp);log(`${c.name}을(를) 물리쳤다. ${loot}과 은화를 챙겼다.`,'system');game.combat=null;renderCombatResult(msg+` 적을 쓰러뜨렸다! ${loot} 획득, 경험치 ${c.xp}.`);saveGame(false);return}let hit=Math.max(1,c.damage-Math.floor(game.stats.vit/3));game.hp=Math.max(0,game.hp-hit);msg+=` ${c.name}의 반격! 체력 ${hit} 피해.`;if(game.hp<=0){game.hp=Math.ceil(game.maxHp*.45);game.mana=Math.ceil(game.maxMana*.4);game.gold=Math.max(0,game.gold-3);log('전투에서 쓰러졌다. 낯선 약초꾼이 당신을 야영지로 옮겼다. 은화 3개를 잃었다.','system');game.combat=null;renderCombatResult('시야가 흐려진다… 눈을 뜨니 안전한 야영지다. 체력이 일부 회복되었다.');saveGame(false);return}renderCombat(msg);saveGame(false)}
function renderCombatResult(msg){$('#modalRoot').innerHTML=`<div class="modal-back"><div class="modal"><div class="eyebrow">전투 종료</div><h2 class="title">기록이 이어진다</h2><p>${esc(msg)}</p><button class="btn" id="continueBtn">계속 여행하기</button></div></div>`;$('#continueBtn').onclick=()=>{$('#modalRoot').innerHTML='';renderGame()}}

