 function fight(move){let c=game.combat;if(!c)return;let msg='',damage=0;if(move==='flee'){if(Math.random()<.58){log(`${c.name}에게서 무사히 벗어났다.`);game.combat=null;$('#modalRoot').innerHTML='';renderGame();saveGame(false);return}else msg='도주로가 막혔다!'}else if(move==='potion'){if(takeItem('약초 연고')){game.hp=Math.min(game.maxHp,game.hp+12);msg='약초 연고를 발랐다. 체력 12 회복.'}else msg='사용할 약초 연고가 없다.'}else if(move.startsWith('skill:')){let sk=move.slice(6);if(['화염구','서리 창','비전 방벽'].includes(sk)){if(game.mana<4){msg='마나가 부족하다!';damage=0}else{game.mana-=4;damage=8+game.stats.wis*2+Math.floor(game.mastery.arcane/2);if(sk==='비전 방벽'){game.hp=Math.min(game.maxHp,game.hp+5);damage=Math.floor(damage*.65)}gainMastery('arcane');msg=`${sk} 발동! 마법의 힘으로 ${damage} 피해를 주었다.`}}else if(['관통 사격','정밀 조준','연발 사격'].includes(sk)){damage=6+game.stats.dex*2+Math.floor(game.mastery.bow/2);gainMastery('bow');msg=`${sk}! 정확한 사격으로 ${damage} 피해.`}else if(sk==='치명적 급습'){damage=7+game.stats.dex*2+game.mastery.tracking;gainMastery('tracking');msg=`기습으로 급소를 노려 ${damage} 피해.`}else{damage=7+game.stats.str*2+game.mastery.blade;gainMastery('blade');msg=`${sk}! 검을 휘둘러 ${damage} 피해.`}}else{damage=4+game.stats.str+game.stats.dex+Math.floor(Math.random()*4);gainMastery(game.startMastery==='bow'?'bow':'blade');msg=`무기를 휘둘러 ${damage} 피해를 주었다.`}c.hp=Math.max(0,c.hp-damage);if(c.hp<=0){let loot=c.name.includes('사슴')||c.name.includes('토끼')||c.name.includes('산양')?'말린 식량':'가죽';addItem(loot,1);if(Math.random()<.45)addItem('말린 식량',1);game.gold+=2+Math.floor(Math.random()*4);gainXp(c.xp);log(`${c.name}을(를) 물리쳤다. ${loot}과 은화를 챙겼다.`,'system');game.combat=null;renderCombatResult(msg+` 적을 쓰러뜨렸다! ${loot} 획득, 경험치 ${c.xp}.`);saveGame(false);return}let hit=Math.max(1,c.damage-Math.floor(game.stats.vit/3));game.hp=Math.max(0,game.hp-hit);msg+=` ${c.name}의 반격! 체력 ${hit} 피해.`;if(game.hp<=0){game.hp=Math.ceil(game.maxHp*.45);game.mana=Math.ceil(game.maxMana*.4);game.gold=Math.max(0,game.gold-3);log('전투에서 쓰러졌다. 낯선 약초꾼이 당신을 야영지로 옮겼다. 은화 3개를 잃었다.','system');game.combat=null;renderCombatResult('시야가 흐려진다… 눈을 뜨니 안전한 야영지다. 체력이 일부 회복되었다.');saveGame(false);return}renderCombat(msg);saveGame(false)}
 function renderCombatResult(msg){$('#modalRoot').innerHTML=`<div class="modal-back"><div class="modal"><div class="eyebrow">전투 종료</div><h2 class="title">기록이 이어진다</h2><p>${esc(msg)}</p><button class="btn" id="continueBtn">계속 여행하기</button></div></div>`;$('#continueBtn').onclick=()=>{$('#modalRoot').innerHTML='';renderGame()}}
+function saveGame(manual=true){if(!game)return;try{localStorage.setItem('ashen-route-save',JSON.stringify(game));if(manual)toast('여정의 기록을 저장했습니다.')}catch(e){if(manual)toast('저장 공간에 접근할 수 없습니다.')}}
+function loadGame(){try{let raw=localStorage.getItem('ashen-route-save');if(raw){let data=JSON.parse(raw);if(data&&data.name&&data.inventory&&data.mastery){game=data;$('#creator').classList.add('hidden');$('#game').classList.remove('hidden');renderGame();if(game.combat)renderCombat('전투가 이어진다. 행동을 선택하라.');return}}}catch(e){localStorage.removeItem('ashen-route-save')}renderCreator()}
+$('#saveBtn').onclick=()=>game?saveGame(true):toast('아직 여정이 시작되지 않았습니다.');$('#resetBtn').onclick=()=>{if(confirm('현재 여정의 기록을 지우고 새 여정을 시작할까요?')){localStorage.removeItem('ashen-route-save');game=null;create={name:'',gender:'여성',race:'human',stats:{str:2,dex:2,vit:2,wis:2},mastery:'blade'};$('#game').classList.add('hidden');$('#modalRoot').innerHTML='';renderCreator()}};
+loadGame();
+</script></body></html>

